import sys
import traceback


def _test(expected, actual, call):
    try:
        assert actual == expected, "{} should return {}. Your code: {}".format(call, expected, actual)
        print("\u2713 passed: {} \u2192 {}".format(call, expected))
    except AssertionError as ae:
        print("\u2717 failed: {}".format(ae))


class SearchTests:

    def __init__(self, module_name):
        self.module = module_name

    def test_01_sequential_found(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            alist = [5, 1, 9, 3, 7]
            _test(expected=(True, 0),
                  actual=self.module.sequential_search(alist, 5),
                  call="sequential_search([5,1,9,3,7], 5)")

            _test(expected=(True, 2),
                  actual=self.module.sequential_search(alist, 9),
                  call="sequential_search([5,1,9,3,7], 9)")

            _test(expected=(True, 4),
                  actual=self.module.sequential_search(alist, 7),
                  call="sequential_search([5,1,9,3,7], 7)")
        except Exception as e:
            print("\u2717 FAILED. calling sequential_search() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_02_sequential_not_found(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            alist = [5, 1, 9, 3, 7]
            _test(expected=(False, None),
                  actual=self.module.sequential_search(alist, 10),
                  call="sequential_search([5,1,9,3,7], 10)")

            _test(expected=(False, None),
                  actual=self.module.sequential_search([], 1),
                  call="sequential_search([], 1)")
        except Exception as e:
            print("\u2717 FAILED. calling sequential_search() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

