    def test_05_smart_type_error(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            alist = [1, "a", 3]
            try:
                self.module.smart_sequential_search(alist, 1)
                print("\u2717 FAILED. smart_sequential_search() did not raise ValueError on non-numeric list")
            except ValueError:
                print("\u2713 passed: smart_sequential_search() raised ValueError on non-numeric list")
        except Exception as e:
            print("\u2717 FAILED. calling smart_sequential_search() raised an unexpected exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

